    Bug 2045571 - Remove redundant nsIMsgFolder.sizeOnDiskWithSubfolders attribute. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D305078

diff --git a/mailnews/base/public/nsIMsgFolder.idl b/mailnews/base/public/nsIMsgFolder.idl
index 8c2ae18916d..833b4311b28 100644
--- a/mailnews/base/public/nsIMsgFolder.idl
+++ b/mailnews/base/public/nsIMsgFolder.idl
@@ -411,16 +411,6 @@ interface nsIMsgFolder : nsISupports {
    */
   attribute long long sizeOnDisk;

-  /**
-   * Aggregate size on disk of this folder and any folder
-   * nested under it.
-   *
-   * This attribute is computed by reading the sizeOnDisk attribute of the
-   * current folder and all of its sub-folders. This means its calculation can
-   * become costly if the folder has a lot of sub-folders.
-   */
-  readonly attribute long long sizeOnDiskWithSubFolders;
-
   readonly attribute ACString username;
   readonly attribute ACString hostname;

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index a40945d89b7..b8f7ceb0b18 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -4223,35 +4223,6 @@ NS_IMETHODIMP nsMsgDBFolder::SetSizeOnDisk(int64_t aSizeOnDisk) {
   return NS_OK;
 }

-NS_IMETHODIMP nsMsgDBFolder::GetSizeOnDiskWithSubFolders(int64_t* sizeOnDisk) {
-  NS_ENSURE_ARG_POINTER(sizeOnDisk);
-
-  int64_t totalSize;
-
-  // Get the size of the current folder.
-  nsresult rv = GetSizeOnDisk(&totalSize);
-  NS_ENSURE_SUCCESS(rv, rv);
-
-  // Iterate over all sub-folders, and add their size to the total.
-  for (auto folder : mSubFolders) {
-    // Ignore virtual folders.
-    uint32_t folderFlags;
-    folder->GetFlags(&folderFlags);
-    if (!(folderFlags & nsMsgFolderFlags::Virtual)) {
-      // Get the nested size on disk for the sub-folder, so it includes any
-      // sub-folder it might have.
-      int64_t size;
-      rv = folder->GetSizeOnDiskWithSubFolders(&size);
-      NS_ENSURE_SUCCESS(rv, rv);
-      totalSize += size;
-    }
-  }
-
-  *sizeOnDisk = totalSize;
-
-  return NS_OK;
-}
-
 NS_IMETHODIMP nsMsgDBFolder::GetUsername(nsACString& userName) {
   nsresult rv;
   nsCOMPtr<nsIMsgIncomingServer> server;
diff --git a/mailnews/base/test/unit/test_nsIMsgFolder.js b/mailnews/base/test/unit/test_nsIMsgFolder.js
index 655949cf3a4..5ac37157927 100644
--- a/mailnews/base/test/unit/test_nsIMsgFolder.js
+++ b/mailnews/base/test/unit/test_nsIMsgFolder.js
@@ -91,23 +91,4 @@ function run_test() {

   // test a normal folder is deletable
   Assert.ok(folder1.deletable);
-
-  // Test computing size on disk, both with and without
-  // including sub-folders.
-
-  folder1.createSubfolder("folder2", null);
-  const subFolder = folder2.getChildNamed("folder2");
-
-  folder1.sizeOnDisk = 1;
-  subFolder.sizeOnDisk = 2;
-
-  // Test that getting sizeOnDisk returns the correct result.
-  Assert.equal(folder1.sizeOnDisk, 1);
-  Assert.equal(subFolder.sizeOnDisk, 2);
-
-  // Test that sizeOnDiskWithSubFolders for `folder1` includes the size of
-  // `subFolder`, but that sizeOnDiskWithSubFolders for `subFolder` has the same
-  // value as its non-nested size because it has no sub-folder of its own.
-  Assert.equal(folder1.sizeOnDiskWithSubFolders, 3);
-  Assert.equal(subFolder.sizeOnDiskWithSubFolders, 2);
 }
